def run():
    app = create_app("development")
    with app.app_context():
        urlless = Scholarship.query.filter(Scholarship.source_url.is_(None)).all()
        deleted_titles = [s.title for s in urlless]
        for s in urlless:
            db.session.delete(s)
        db.session.commit()
        print(f"Deleted {len(deleted_titles)} scholarships that had no source_url.")

        added = 0
        for data in NEW_SCHOLARSHIPS:
            exists = Scholarship.query.filter_by(
                source_name=data["source_name"], external_id=data["external_id"]
            ).first()
            if exists:
                continue
            db.session.add(Scholarship(**data))
            added += 1
        db.session.commit()
        print(f"Added {added} new scholarships with verified real URLs.")

        total = Scholarship.query.count()
        with_url = Scholarship.query.filter(Scholarship.source_url.isnot(None)).count()
        print(f"{with_url} of {total} scholarships now have a URL.")


if __name__ == "__main__":
    run()
